/**
 * @name Trace data flow to eval/exec
 * @description Trace where the input to eval/exec comes from
 * @kind path-problem
 * @problem.severity error
 * @id py/trace-eval-exec
 * @tags security
 *       external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module EvalFlowConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    sink = API::builtin(["eval", "exec", "compile"]).getACall().getArg(0)
  }
}

module EvalFlow = TaintTracking::Global<EvalFlowConfig>;
import EvalFlow::PathGraph

from EvalFlow::PathNode source, EvalFlow::PathNode sink
where EvalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Data flow to eval/exec from parameter $@", source.getNode(), source.getNode().toString()
